actions.script:
const out = ec.service.sync().name('org.moqui.chat.ChatKeyServices.update#ChatDevice').parameters({deviceId: deviceId || '',
    displayName: displayName || ''}).requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({errors, reasonCode: out.reasonCode || null})

const out = ec.service.sync().name('org.moqui.chat.ChatKeyServices.revoke#ChatDevice').parameter('deviceId', deviceId || '')
    .requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({errors, reasonCode: out.reasonCode || null})

const out = ec.service.sync().name('org.moqui.chat.ChatKeyServices.store#ChatKeySettings')
    .parameter('verifiedDevicesOnly', String(verifiedDevicesOnly) === 'true').requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({errors, verifiedDevicesOnly: !!out.verifiedDevicesOnly})
